<?php

namespace App\Services\Doku;

/**
 * DOKU BCA Virtual Account, Direct API (SNAP), with the VA number generated by DOKU (DGPC).
 * The number is shown on Orlena's own page; the VA is closed-amount, single use and expires with the payment.
 * Works in the DOKU sandbox (pay it with the DOKU VA simulator).
 */
class DokuVaClient
{
    public const CREATE_PATH = '/virtual-accounts/bi-snap-va/v1.1/transfer-va/create-va';

    public const STATUS_PATH = '/orders/v1.0/transfer-va/status';

    public const DELETE_PATH = '/virtual-accounts/bi-snap-va/v1.1/transfer-va/delete-va';

    /** Default additionalInfo.channel; DOKU_VA_BCA_CHANNEL overrides it. */
    public const CHANNEL = 'VIRTUAL_ACCOUNT_BCA';

    public function __construct(private DokuSnapClient $snap) {}

    private function channel(): string
    {
        return (string) (config('services.doku.va_bca_channel') ?: self::CHANNEL);
    }

    /** Returns the full virtualAccountNo (with DOKU's leading-space padding) and DOKU's how-to-pay page. */
    public function create(string $trxId, int $amount, string $name, \DateTimeInterface $expiresAt): array
    {
        $serviceId = $this->serviceId();
        $prefix = (string) config('services.doku.va_bca_customer_prefix');
        $response = $this->snap->send(self::CREATE_PATH, [
            'partnerServiceId' => $serviceId, 'customerNo' => $prefix, 'virtualAccountNo' => $serviceId.$prefix,
            'virtualAccountName' => $this->name($name), 'trxId' => $trxId,
            'totalAmount' => ['value' => $amount.'.00', 'currency' => 'IDR'],
            'additionalInfo' => ['channel' => $this->channel(), 'virtualAccountConfig' => ['reusableStatus' => false]],
            'virtualAccountTrxType' => 'C',
            'expiredDate' => (new \DateTimeImmutable('@'.$expiresAt->getTimestamp()))->setTimezone(new \DateTimeZone('Asia/Jakarta'))->format('Y-m-d\TH:i:sP'),
        ]);
        $number = $response->json('virtualAccountData.virtualAccountNo');
        if (! $this->snap->ok($response) || ! is_string($number) || trim($number) === '') {
            throw new DokuException('DOKU could not create the BCA Virtual Account'.$this->snap->reason($response));
        }

        return ['va' => $number, 'how_to_pay' => $response->json('virtualAccountData.additionalInfo.howToPayPage')];
    }

    /** Current status as the fields ApplyPaymentStatus reads. Anything not clearly paid stays PENDING. */
    public function status(string $virtualAccountNo, string $trxId): array
    {
        $response = $this->snap->send(self::STATUS_PATH, $this->identity($virtualAccountNo));
        if (! $this->snap->ok($response)) {
            throw new DokuException('Could not read the Virtual Account status'.$this->snap->reason($response));
        }
        $data = $response->json('virtualAccountData');
        // Without an inquiry id DOKU may answer with every transaction on the VA; ours is single use, so take the latest.
        if (is_array($data) && array_is_list($data)) {
            $data = end($data) ?: [];
        }
        $data = is_array($data) ? $data : [];
        $flag = strtolower((string) ($data['paymentFlagReason']['english'] ?? ''));
        $paid = ($data['paymentFlagStatus'] ?? null) === '00' || in_array($flag, ['success', 'paid', 'successful'], true);

        return [
            'order_id' => $trxId, 'transaction_status' => $paid ? 'SUCCESS' : 'PENDING',
            'gross_amount' => $data['paidAmount']['value'] ?? $data['totalAmount']['value'] ?? null,
            'payment_type' => 'VA-BCA', 'transaction_date' => $data['trxDateTime'] ?? null,
        ];
    }

    /** Best effort: closes an unpaid VA so it can no longer be paid. */
    public function delete(string $virtualAccountNo, string $trxId): bool
    {
        try {
            return $this->snap->ok($this->snap->send(self::DELETE_PATH, [
                ...$this->identity($virtualAccountNo), 'trxId' => $trxId, 'additionalInfo' => ['channel' => $this->channel()],
            ], 'DELETE'));
        } catch (DokuException) {
            return false;
        }
    }

    /** partnerServiceId is the first 8 characters (space padded); customerNo is the rest. */
    private function identity(string $virtualAccountNo): array
    {
        return ['partnerServiceId' => substr($virtualAccountNo, 0, 8), 'customerNo' => substr($virtualAccountNo, 8), 'virtualAccountNo' => $virtualAccountNo];
    }

    private function serviceId(): string
    {
        $id = trim((string) config('services.doku.va_bca_partner_service_id'));
        if ($id === '' || strlen($id) > 8) {
            throw new DokuException('DOKU BCA VA settings are incomplete (va_bca_partner_service_id)');
        }

        return str_pad($id, 8, ' ', STR_PAD_LEFT);
    }

    /** Shown by BCA when paying; letters, digits and spaces only. */
    private function name(string $name): string
    {
        $clean = trim((string) preg_replace('/\s+/', ' ', (string) preg_replace('/[^\pL\pN ]/u', ' ', $name)));

        return mb_substr($clean !== '' ? $clean : 'Pelanggan Orlena', 0, 40);
    }
}
